/* From Uiverse.io by Yaya12085 - Tags: progress, card, shadow, radio, quizz, select */
.__UIV_SCOPE__ .radio-input input {
  display: none;
}

.__UIV_SCOPE__ .radio-input {
  display: flex;
  flex-direction: column;
  padding: 12px;
  background: #fff;
  color: #000;
  border-radius: 10px;
  box-shadow: 0px 87px 78px -39px rgba(0,0,0,0.4);
  width: 320px;
}

.__UIV_SCOPE__ .info {
  margin-bottom: 10px;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.__UIV_SCOPE__ .question {
  color: rgb(49, 49, 49);
  font-size: 1rem;
  line-height: 1rem;
  font-weight: 800;
}

.__UIV_SCOPE__ .steps {
  background-color: rgb(0, 0, 0);
  padding: 4px;
  color: #fff;
  border-radius: 4px;
  font-size: 12px;
  line-height: 12px;
  font-weight: 600;
}

.__UIV_SCOPE__ .radio-input  label {
  display: flex;
  background-color: #fff;
  padding: 14px;
  margin: 8px 0 0 0;
  font-size: 13px;
  font-weight: 600;
  border-radius: 10px;
  cursor: pointer;
  border: 1px solid rgba(187, 187, 187, 0.164);
  color: #000;
  transition: .3s ease;
}

.__UIV_SCOPE__ .radio-input  label:hover {
  background-color: rgba(24, 24, 24, 0.13);
  border: 1px solid #bbb;
}

.__UIV_SCOPE__ .result {
  margin-top: 10px;
  font-weight: 600;
  font-size: 12px;
  display: none;
  transition: display .4s ease;
}

.__UIV_SCOPE__ .result.success {
  color: green;
}

.__UIV_SCOPE__ .result.error {
  color: red;
}

.__UIV_SCOPE__ .radio-input input:checked + label {
  border-color: red;
  color: red;
}

.__UIV_SCOPE__ .radio-input input[value="value-2"]:checked + label {
  border-color: rgb(22, 245, 22);
  color: rgb(16, 184, 16);
}

.__UIV_SCOPE__ .radio-input:has(input[value="value-2"]:checked) .result.success {
  display: flex;
}

.__UIV_SCOPE__ .radio-input:has(input:not([value="value-2"]):checked ) .result.error {
  display: flex;
}
